```python
def manage_bank_account():
    """Manage a bank account with deposit, withdrawal, and balance inquiry functions."""

    # Initialize the bank account dictionary
    account = {
        "balance": 0,
        "transactions": []
    }

    def deposit(amount):
        """Deposit money into the bank account."""
        if amount > 0:
            account["balance"] += amount
            account["transactions"].append({"type": "deposit", "amount": amount})
            return f"New balance: {account['balance']}"
        else:
            print("Error: Deposit amount must be positive.")
            return ""

    def withdrawal(amount):
        """Withdraw money from the bank account."""
        if amount > 0 and account["balance"] >= amount:
            account["balance"] -= amount
            account["transactions"].append({"type": "withdrawal", "amount": amount})
            return f"New balance: {account['balance']}"
        else:
            print("Error: Insufficient funds or withdrawal amount must be positive.")
            return ""

    def balance_inquiry():
        """Display the current balance of the bank account."""
        print(f"Current balance: {account['balance']}")
        print("Transactions:")
        for transaction in account["transactions"]:
            print(f"- {transaction['type']}: ${transaction['amount']}")

    while True:
        print("\nAvailable options:")
        print("1. Deposit")
        print("2. Withdrawal")
        print("3. Balance Inquiry")
        print("4. Exit")

        option = input("Enter your choice: ")

        if option == "1":
            amount = float(input("Enter the deposit amount: "))
            print(deposit(amount))

        elif option == "2":
            amount = float(input("Enter the withdrawal amount: "))
            print(withdrawal(amount))

        elif option == "3":
            balance_inquiry()

        elif option == "4":
            print("Exiting the program...")
            break

        else:
            print("Error: Invalid option. Please try again.")


if __name__ == "__main__":
    manage_bank_account()
```

This program will allow you to manage your bank account with deposit, withdrawal, and balance inquiry functions. You can run the program and enter the required inputs to perform the desired transactions.
